package sn.ticket.api;
import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import java.util.*;
@RestControllerAdvice public class ApiErrors { @ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class}) ResponseEntity<?> bad(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));} @ExceptionHandler(NoSuchElementException.class) ResponseEntity<?> missing(Exception e){return ResponseEntity.status(404).body(Map.of("error",e.getMessage()));} @ExceptionHandler(SecurityException.class) ResponseEntity<?> denied(Exception e){return ResponseEntity.status(401).body(Map.of("error",e.getMessage()));} @ExceptionHandler(Exception.class) ResponseEntity<?> generic(Exception e){return ResponseEntity.status(500).body(Map.of("error","Erreur serveur."));} }
